cat > examples/diag_pieces.rs <<'EOF'
use kernel::outline::stroke_pieces;
use kernel::{Anchor, NibShape, Stroke};
use kurbo::{Point, Shape};
fn main() {
    let nib = NibShape { width: 40.0, height: 6.0, exponent: 8.0 };
    let an = |x: f64, angle: f64| Anchor { point: Point::new(x, 0.0), handle_in: None, handle_out: None, angle, lift: 1.0 };
    let stroke = Stroke { anchors: vec![an(0.0, 1.3), an(80.0, 0.0)], closed: false };
    let pieces = stroke_pieces(&stroke, &nib, 0.02);
    println!("{} pieces", pieces.len());
    for (i, p) in pieces.iter().enumerate() {
        let bb = p.bounding_box();
        println!("piece {i}: {} els, bbox x {:.2}..{:.2} y {:.2}..{:.2}, area {:.1}", p.elements().len(), bb.x0, bb.x1, bb.y0, bb.y1, p.area());
    }
    let which: Vec<usize> = std::env::args().skip(1).filter_map(|a| a.parse().ok()).collect();
    if !which.is_empty() {
        let sub: Vec<_> = which.iter().map(|&i| pieces[i].clone()).collect();
        let t = std::time::Instant::now();
        let out = kernel::boolean::union(&sub, 0.02);
        println!("union of {:?}: {} els in {:?}", which, out.elements().len(), t.elapsed());
    }
}
EOF
